#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.080233345, -0.178752345, 0.007974555000000001], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.07045138499999999, 'zmax': 0.070451385, 'profiles': [{'outer': [[-0.076254885, 0.039033395], [-0.074912075, 0.04422066500000002], [-0.07303580500000001, 0.049389555], [-0.070478965, 0.054871185], [-0.06751742499999999, 0.06083102500000001], [-0.0660650430993233, 0.06414807052826293], [-0.064555905, 0.067986535], [-0.062661245, 0.07475574500000001], [-0.060233155000000003, 0.081249045], [-0.054972295, 0.085479805], [-0.049067615, 0.088312575], [-0.042647895, 0.100968075], [-0.036651255, 0.10656001500000001], [-0.030305105, 0.111692125], [-0.022358625, 0.11616201500000001], [-0.014338575, 0.118332565], [-0.006226554999999998, 0.11930750500000001], [-0.0039185854581154315, 0.11965800539295153], [0.0030443350000000013, 0.12107336500000002], [0.010770075, 0.122784065], [0.020445645000000002, 0.12442119500000001], [0.028281755000000002, 0.12442119500000001], [0.030525895, 0.12385095500000001], [0.037846945, 0.12140445500000001], [0.040109485, 0.12046633500000001], [0.046749935, 0.117118515], [0.053004105, 0.113090085], [0.058614475, 0.10812352500000001], [0.062918805, 0.10194296500000001], [0.065880335, 0.095118565], [0.068418795, 0.088183775], [0.070607745, 0.081138655], [0.072502395, 0.073983145], [0.074047535, 0.066754055], [0.07531676500000001, 0.059469775], [0.076291675, 0.05214871500000001], [0.07699066500000001, 0.044606935000000014], [0.077395345, 0.03732265500000001], [0.07756089499999999, 0.030019985], [0.07743213500000001, 0.022735695], [0.077045845, 0.015451445000000008], [0.076383645, 0.00820399500000002], [0.075463895, 0.0009932950000000051], [0.074249855, -0.006180605000000006], [0.072759885, -0.013299304999999984], [0.07095721499999999, -0.02036284499999999], [0.068841835, -0.027334405000000006], [0.066395355, -0.03421397499999998], [0.063562585, -0.041001604999999997], [0.060343515, -0.047678845], [0.056627805, -0.054172145000000005], [0.053151215, -0.060830995], [0.051219785000000004, -0.06809689499999999], [0.049693025, -0.07547311500000001], [0.046897035000000004, -0.090243985], [0.045407075, -0.09754665500000001], [0.043751555000000004, -0.104389445], [0.041672955000000005, -0.11123226499999997], [0.039447215, -0.11662183499999998], [0.036099385, -0.120705445], [0.035290015, -0.121809115], [0.030544215, -0.123722215], [0.029072645, -0.12412683500000002], [0.024326835, -0.12442119500000001], [0.017943895, -0.12407167500000002], [0.013345245000000002, -0.12348304499999999], [0.007550945000000002, -0.122544935], [-0.00011960499999999832, -0.12105496499999999], [-0.009132965, -0.11908676500000001], [-0.014559384999999998, -0.11776231499999998], [-0.018477435, -0.11673219500000001], [-0.020059365, -0.11621721500000001], [-0.023903845, -0.114690445], [-0.025173074999999996, -0.11362351499999998], [-0.027214875, -0.111636865], [-0.028116215, -0.11049641499999999], [-0.030305165000000002, -0.105952935], [-0.031960695, -0.100655305], [-0.033505824999999996, -0.09401484499999999], [-0.034756655, -0.08801822499999998], [-0.035878725, -0.08180083499999999], [-0.039778395, -0.056121934999999984], [-0.040863655, -0.04981260499999998], [-0.042372025, -0.043944705], [-0.044413825, -0.03892298499999999], [-0.045958965, -0.034489885], [-0.047448935, -0.030682194999999995], [-0.050759954999999995, -0.028603605000000004], [-0.054604425000000005, -0.027058444999999987], [-0.058467305000000004, -0.025035045000000006], [-0.059092715, -0.024446415], [-0.061612775, -0.020638724999999997], [-0.06256930499999999, -0.016076855], [-0.06396729500000001, -0.011294294999999982], [-0.0663700882521804, -0.005836459908762141], [-0.07263114500000001, 0.004819435000000011], [-0.075169605, 0.010209035000000005], [-0.07688030500000001, 0.015929744999999995], [-0.077524115, 0.02188963500000002], [-0.07756089499999999, 0.028033415000000006], [-0.077137825, 0.03362537500000001]], 'holes': []}], 'simplify_tolerance': 4.976847800000001e-05, 'sketch_entity_count': 107}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
